function top5Card(){if(!model)return '';const f=scope.kind==='account'?h=>h.account_id===scope.id:scope.kind==='instrument'?h=>h.code===scope.id&&(!scope.account||h.account_id===scope.account):null;let d;try{d=compData(f,true)}catch(e){return ''}const head='<div class="mu-card-head"><span>'+ic('bars')+'<h2>계좌 주요 종목</h2></span><a class="mu-sub-link" href="management.html?mode=composition">구성 보기 →</a></div>';if(!d.held)return '<section class="mu-card uat-top5" data-top5="0">'+head+'<p class="ft">보유 종목이 없어요. 거래를 등록하면 표시됩니다.</p></section>';const pos=d.rows.filter(r=>r.amt&&r.amt.cmp('0')>0),top=pos.slice(0,5),rest=pos.slice(5),T=d.vtotal;const li=(i,c,n,a)=>'<li data-rank="'+i+'" data-color="'+c+'"><span class="rk">'+i+'</span><i class="sw" style="background:'+c+'"></i><span class="nm">'+esc(n)+'</span><span class="v"><b>'+pctStr(a,T)+'</b><small>'+won(a)+'</small></span></li>';let h=top.map((r,i)=>li(i+1,PAL[i],r.name,r.amt)).join('');if(rest.length){const s=rest.reduce((v,r)=>v.add(r.amt),L.D.of('0'));h+=li('기타',PAL_ETC,'기타 '+rest.length+'개',s)}return '<section class="mu-card uat-top5" data-top5="'+top.length+'">'+head+(pos.length?'<ol>'+h+'</ol>':'<p class="ft">평가액을 확인할 수 있는 종목이 없어요(0원으로 계산하지 않음).</p>')+'<p class="ft">현재 평가액 기준 순위·비중 · 합계 '+(T?won(T):'—')+' · 내 투자금 구성(평가액) 도넛과 같은 계산'+(d.missing.length?'<br><span class="miss">가격 미확인 '+d.missing.length+'종목 제외: '+esc(d.missing.join(', '))+'</span>':'')+'</p></section>'}

/* t198 U26 정정(대표 승인 2+3): 실제 입금 확인액과 계산상 배당 추정액 분리. 원장·원장키·CORE·세금·replay 불변(표시 계층 파생).
   실입금 근거 = (a) 기존 사용자 확정 실입금액(state.dividend_confirmations, 읽기 전용) 또는 (b) 별도 비원장 키 dnmuat194.receipt.evidence.v1의 증권사 입금 증빙(계좌·월 합계, 선택적 종목별 금액).
   근거 없는 회차 = '보류(권리 확인 필요)' → 실입금·배당현금·현재가치·총수익에 미반영. 남은 현금은 계좌별(실입금 − 재투자 − 사용), 계좌 간 상계 금지, 부족분 = '재원 미확인'. */
const EVK='dnmuat194.receipt.evidence.v1';
function evItems(){try{const d=JSON.parse(localStorage.getItem(EVK));return d&&Array.isArray(d.items)?d.items.filter(x=>x&&x.account_id&&/^\d{4}-\d{2}$/.test(x.month)&&x.amount!=null):[]}catch{return []}}
function dAmt(e){return recvOf(model,x=>x===e)}
let RCM=null;
function rcCore(){if(RCM&&RCM.m===model)return RCM;const Z=L.D.of('0'),divs=model.events.filter(e=>e.kind==='dividend'),st=new Map(),cf=new Set((state.dividend_confirmations||[]).map(c=>c.account_id+':'+c.distribution_id)),off=[];
 for(const it of evItems()){const evs=divs.filter(e=>e.account_id===it.account_id&&e.date.startsWith(it.month));let got=Z;for(const e of evs){if(it.codes){const v=it.codes[e.code];if(v==null)continue;const a=L.D.of(String(v));st.set(e,{s:a.cmp(dAmt(e))===0?'ok':'mismatch',amt:a,src:it.source||'증권사 증빙'});got=got.add(a)}else{const a=dAmt(e);st.set(e,{s:'month',amt:a,src:it.source||'증권사 월합계'});got=got.add(a)}}const d=L.D.of(String(it.amount)).sub(got);if(d.cmp('0')!==0)off.push({account_id:it.account_id,month:it.month,amt:d})}
 for(const e of divs)if(!st.has(e))st.set(e,cf.has(e.account_id+':'+e.distribution_id)?{s:'ok',amt:dAmt(e),src:'실입금액 확정'}:{s:'hold',amt:dAmt(e)});
 RCM={m:model,st,off};return RCM}
/* t257: 가상 이월재원(검증용)은 실입금(actual)과 분리, 재원 계산에만 사용 */
function synOf(a){try{const v=model.synthetic&&model.synthetic.get(a);return v||L.D.of('0')}catch(e){return L.D.of('0')}}
function synTotal(){try{return (state.dividend_cash_openings||[]).reduce((v,o)=>v.add(o.amount),L.D.of('0'))}catch(e){return L.D.of('0')}}
function synBanner(){return '';const o=state&&state.dividend_cash_openings;if(!o||!o.length)return '';return '<div class="mu-syn-warn" role="alert"><b>검증용 원장 · 가상 이월재원(검증용) '+won(synTotal())+'</b><small>테스트 전용 가상 배당현금입니다. 실제 입금·실입금 확인 배당·투자원금에 포함하지 않으며 실사용 입금확정에 쓰지 마세요.</small></div>'}
function rcStat(e){return rcCore().st.get(e)}
function rcOf(ef){const Z=L.D.of('0'),c=rcCore(),acc=new Map(),A=a=>{if(!acc.has(a))acc.set(a,{actual:Z,calc:Z,hold:Z,off:Z,spent:Z,used:Z,nA:0,nH:0});return acc.get(a)};let nA=0,nH=0;
 for(const e of model.events){if(!ef(e))continue;const a=A(e.account_id);if(e.kind==='dividend'){const x=c.st.get(e);a.calc=a.calc.add(x.amt);if(x.s==='hold'){a.hold=a.hold.add(x.amt);a.nH++;nH++}else{a.actual=a.actual.add(x.amt);a.nA++;nA++}}else if(e.kind==='trade'&&e.type==='reinvest')a.spent=a.spent.add(e.amount);else if(e.kind==='use')a.used=a.used.add(e.amount)}
 for(const o of c.off)if(ef({kind:'evidence',account_id:o.account_id})){const a=A(o.account_id);a.off=a.off.add(o.amt);a.actual=a.actual.add(o.amt)}
 let actual=Z,hold=Z,calc=Z,off=Z,spent=Z,used=Z,cash=Z,short=Z;const shortAcc=[];
 for(const [id,a] of acc){let r=a.actual.add(synOf(id)).sub(a.spent).sub(a.used);a.short=r.cmp('0')<0?Z.sub(r):Z;a.cash=r.cmp('0')<0?Z:r;actual=actual.add(a.actual);hold=hold.add(a.hold);calc=calc.add(a.calc);off=off.add(a.off);spent=spent.add(a.spent);used=used.add(a.used);cash=cash.add(a.cash);short=short.add(a.short);if(a.short.cmp('0')>0)shortAcc.push(id)}
 return {actual,hold,calc,off,spent,used,cash,short,shortAcc,acc,nA,nH}}
function rcApply(p){try{const r=rcOf(eventScope);p.rc=r;if(scope.kind!=='instrument'){p.ledger_cash=p.cash;p.cash=r.cash;p.grown=p.reinvest;p.total=p.direct.add(p.reinvest)}}catch(e){p.rc=null}return p}
function rcCash(a){try{const x=rcOf(e=>e.account_id===a).acc.get(a);return x?x.cash:L.D.of('0')}catch{return model.cash.get(a)}}
function rcNote(r){if(!r)return '';return '보류(권리 확인 필요) '+r.nH+'건 '+won(r.hold)+' · 실입금·현금 미반영'+(r.off.cmp('0')!==0?' · 증빙 월합계 중 원장 회차 미상 '+won(r.off)+' 포함':'')+(r.short.cmp('0')>0?' · 재원 미확인 '+won(r.short):'')}
window.__dnmRC=()=>({rc:rcOf(()=>true),st:[...rcCore().st].map(([e,x])=>({a:e.account_id,c:e.code,d:e.date,q:e.quantity.str(0),s:x.s,amt:x.amt.str(0)})),off:rcCore().off.map(o=>({a:o.account_id,m:o.month,amt:o.amt.str(0)}))});

/* t199 실입금 입력(대표 승인 A): 계좌·월 합계만 이 기기 localStorage(EVK)에 저장. 원장 키·백업 파일·저장소와 무관. 같은 계좌·월은 1건(덮어쓰기) → 월합계가 그 달 회차를 대체해 이중 집계 없음. */
const actStr=r=>r&&r.nA===0&&r.off.cmp('0')===0&&r.nH>0?'미확인':won(r?r.actual:L.D.of('0'));
function evSave(items){localStorage.setItem(EVK,JSON.stringify({version:1,items}));RCM=null}
function receipt(simple){if(simple===undefined)simple=!!document.querySelector('.bp');const items=evItems(),Z=L.D.of('0'),all=rcOf(()=>true),rowsA=state.accounts.map(a=>{const x=all.acc.get(a.account_id)||{actual:Z,hold:Z,spent:Z,cash:Z,short:Z,nA:0,nH:0,off:Z};return '<tr><td>'+lblH(a)+'</td><td>'+actStr(x)+'</td><td>'+won(x.hold)+'</td><td>'+won(x.spent)+'</td><td>'+won(x.cash)+'</td><td>'+(x.short.cmp('0')>0?'재원 미확인 '+won(x.short):'—')+'</td></tr>'}).join('');
 const list=items.length?'<ul class="mu-ev-list">'+items.map((x,i)=>'<li>'+esc(lbl(accOf(x.account_id))||'알 수 없는 계좌')+' · '+esc(x.month)+' · <b>'+won(L.D.of(String(x.amount)))+'</b> <button type="button" class="lab-btn" data-ev-del="'+i+'">삭제</button></li>').join('')+'</ul>':'<p class="record-note">입력한 실입금이 없어요.</p>';
 const d=simple?dialog('실수령 배당 입력','<p class="record-note ev-simple">실제 받은 배당금 합계를 계좌·월별로 입력하세요. 같은 계좌·월은 다시 입력하면 바뀝니다.</p>'+list.replace('입력한 실입금이 없어요.','받은 배당금 기록 없음')+'<form id="ev-form"><label>계좌<select name="account" required>'+state.accounts.map(a=>'<option value="'+esc(a.account_id)+'">'+esc(lbl(a))+'</option>').join('')+'</select></label><label>입금 월<input name="month" type="month" required></label><label>받은 배당금(원)<input name="amount" inputmode="numeric" required></label><p class="form-error" role="alert"></p><button class="lab-btn lab-primary" type="submit">저장</button><button class="lab-btn" type="button" data-close>닫기</button></form>'):dialog('증권사 실입금 확인','<p class="record-note">증권사 앱의 계좌별 <b>월 배당 입금 합계</b>를 입력하세요. 이 기기에만 저장되고 원장·백업 파일에는 들어가지 않아요. 같은 계좌·월을 다시 입력하면 바뀝니다.</p>'+list+'<form id="ev-form"><label>계좌<select name="account" required>'+state.accounts.map(a=>'<option value="'+esc(a.account_id)+'">'+esc(lbl(a))+'</option>').join('')+'</select></label><label>입금 월<input name="month" type="month" required></label><label>입금 합계(원)<input name="amount" inputmode="numeric" required></label><p class="form-error" role="alert"></p><button class="lab-btn lab-primary" type="submit">실입금으로 저장</button><button class="lab-btn" type="button" data-close>닫기</button></form><div class="comparison-table-wrap"><table class="mu-ev-table"><thead><tr><th>계좌</th><th>실입금 확인</th><th>계산상 미확인</th><th>재투자 사용</th><th>남은 현금</th><th>재원</th></tr></thead><tbody>'+rowsA+'</tbody></table></div>');
 const f=d.querySelector('#ev-form'),err=f.querySelector('.form-error');
 d.querySelectorAll('[data-ev-del]').forEach(b=>b.addEventListener('click',()=>{const it=evItems();it.splice(Number(b.dataset.evDel),1);evSave(it);render();receipt(simple)}));
 f.addEventListener('submit',e=>{e.preventDefault();try{const v=f.amount.value.trim().replace(/[,원\s]/g,'');if(!/^(0|[1-9]\d*)$/.test(v))throw Error('원 단위 정수로 입력해 주세요.');if(!/^\d{4}-\d{2}$/.test(f.month.value))throw Error('입금 월을 선택해 주세요.');const it=evItems().filter(x=>!(x.account_id===f.account.value&&x.month===f.month.value));it.push({account_id:f.account.value,month:f.month.value,amount:v,source:'대표 입력'});it.sort((a,b)=>(a.account_id+a.month).localeCompare(b.account_id+b.month));evSave(it);render();receipt()}catch(x){err.textContent=x.message||'저장하지 못했어요.'}})}
function homePerf(){try{const hf=scope.kind==='account'?h=>h.account_id===scope.id:scope.kind==='instrument'?h=>h.code===scope.id&&(!scope.account||h.account_id===scope.account):()=>true,r=perfOf(hf,eventScope);return {r:r,grid:'<div class="pf-home"><span><small>투자원금</small><b>'+won(r.cost)+'</b></span><span><small>주가 손익</small><b class="'+pfC(r.pnl)+'">'+pfS(r.pnl)+pfP(r.pnl,r.cost)+'</b></span><span><small>실입금 확인 배당 ('+BLx()+')</small><b class="'+pfC(r.recv)+'">'+pfS(r.recv)+'</b></span><span><small>추정 손익 (미확정)</small><b class="'+pfC(r.total)+'">'+pfS(r.total)+pfP(r.total,r.cost)+'</b></span></div>',split:'<p class="record-note">추정 손익은 과거 거래 불완전 · 확정 아님<br>'+pfSplit(r)+'<br>계산상 배당(보류)·미확인 배당현금은 추정 손익에 미포함</p>'}}catch(e){return {r:null,grid:'',split:''}}}
/* t254: 홈 요약 카드 정보 구조(표시만). 값·계산 무변경, 기존 문구는 펼침 영역으로 이동. */
function homeCalc(p,inst){const hp=homePerf(),r=hp.r,pos=v=>{try{return !!v&&v.cmp('0')>0}catch(e){return false}},et=etcNote(),uc=(inst||!p.complete)?'':'<p class="mu-def mu-uc">별도 항목 · 미확인 배당현금 (실제 잔고 아님) '+won(p.cash)+' (확인 자산·추정 손익에 미포함)</p>',sec=(h,b)=>b?'<div class="mu-calc-sec"><h3>'+h+'</h3>'+b+'</div>':'';const un=!p.complete||pos(p.cash)||(r&&r.rc&&(r.rc.nH>0||pos(r.rc.short)||(r.rc.off&&r.rc.off.cmp('0')!==0)));const body=sec('미확인 배당현금',uc)+sec('추정 손익 산식 · 실입금 · 보류 · 재원 미확인 · 회차 미상',hp.split)+sec('기타 ETF 시세 · 출처 · 기준일',et);return hp.grid+(un?'<p class="mu-def mu-unc" role="note">미확인 항목 있음 · 확인 자산·추정 손익에 합산하지 않았어요</p>':'')+(body?'<div class="mu-calc"><button type="button" class="mu-calc-toggle" aria-expanded="false" aria-controls="mu-calc-body"><span>계산 기준·미확인 항목 펼쳐보기</span><i class="mu-chev" aria-hidden="true"></i></button><div id="mu-calc-body" class="mu-calc-body" hidden>'+body+'</div></div>':'')}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('.mu-calc-toggle');if(!b)return;const o=b.getAttribute('aria-expanded')!=='true',x=document.getElementById(b.getAttribute('aria-controls'));b.setAttribute('aria-expanded',String(o));b.querySelector('span').textContent=o?'계산 기준·미확인 항목 접기':'계산 기준·미확인 항목 펼쳐보기';if(x)x.hidden=!o});
function home(p){const inst=scope.kind==='instrument',nt=notices(p);return synBanner()+'<section class="mu-hero"><div class="mu-hero-text"><h1>지금 내 배당투자는?</h1><div class="mu-hero-meta"><span class="basis mc-basis">'+esc(priceBasis)+'</span>'+(nt?'<a class="mu-pill" href="#mc-notices">확인 필요 알림</a>':'')+'</div><span class="mu-label">'+(inst?'현재 종목가치':'확인 자산')+'</span><div class="mu-amt">'+(p.complete?won(p.total):'평가액 미확인')+'</div><p class="mu-def">'+(p.complete?(inst?'종목 평가액 · 계좌 공유현금 별도':'ETF 평가액 · 미확인 배당현금 제외'):'확인된 평가액 + 해당 범위 배당현금: '+won(p.total))+'</p>'+homeCalc(p,inst)+'<div class="mu-duo mu-u02"><a class="mu-card mu-next-btn mu-u02-ledger" href="management.html?mode=ledger">'+ic('recdoc')+'<span><b>계좌·거래 관리</b><small>보유 종목과 거래 내역</small></span><i class="mu-chev" aria-hidden="true"></i></a><a class="mu-card mu-next-btn mu-u02-weather" href="weather.html">'+ic('cloud')+'<span><b>배당의 미래날씨</b><small>재투자·인출 시뮬레이션</small></span><i class="mu-chev" aria-hidden="true"></i></a></div>'+'</div><img class="mu-hero-tree" src="'+A+'home_large_glowing_tree.webp" alt="" aria-hidden="true"></section><div class="mu-duo"><a class="mu-card mu-stat mu-grown" href="management.html?mode=performance" aria-label="배당이 키운 자산 · 배당 성장과 흐름 보기">'+ic('badge','mu-stat-i')+'<span class="mu-stat-t">배당이 키운 자산<i class="mu-chev" aria-hidden="true"></i></span><b class="green">'+amount(p,p.grown)+'</b><small>'+quantityNote(p)+'</small></a><a class="mu-card mu-stat mu-cost" href="management.html?mode=composition" aria-label="내 투자금 · 내 투자금 보기">'+ic('coin-stack','mu-stat-i')+'<span class="mu-stat-t">내 투자금<i class="mu-chev" aria-hidden="true"></i></span><b>'+won(p.direct_cost)+'</b><small>직접 투자금의 분석</small></a></div>'+breakdown(p)+top5Card()+flowCard(p,'management.html?mode=performance')+''+(readOnly?'':'<button class="mu-fab trade-launch uat-home-fab" data-action="trade" type="button"><span aria-hidden="true">+</span> 거래 등록</button>')+(nt?'<div id="mc-notices" class="mu-notices">'+nt+'</div>':'')}
/* 월별 원금/배당 기여: 새 계산 없음. 각 월말(당월은 오늘)을 기준일로 기존 L.replay/L.project를 호출해
   직접투자 취득원가(direct_cost)와 받은 배당 누적(received, 종목 범위는 기존 화면과 같은 dividend 이벤트 합)을 그대로 읽는다. 월별 시가 자료는 없으므로 원가 기준. */
function monthSeries(){const months=L.months(model,scope);const out=[];for(const m of months){const [y,mm]=m.month.split('-').map(Number),end=new Date(Date.UTC(y,mm,0)).toISOString().slice(0,10),cut=end>L.today()?L.today():end;try{const st=structuredClone(state);st.transactions=st.transactions.filter(t=>t.trade_date<=cut);st.dividend_uses=st.dividend_uses.filter(u=>u.use_date<=cut);const r=RP(st,db,cut),p=L.project(r,null,scope,cut);let rec=recvOf(r,eventScope);out.push({month:m.month,partial:m.partial,cost:p.direct_cost,div:rec})}catch(e){out.push({month:m.month,partial:m.partial,error:e.message})}}return out}
function chart(){const all=monthSeries();if(!all.length)return '<div class="empty-records">거래 기록이 생기면 월별 원금과 배당 기여가 표시돼요.</div>';const data=all.slice(-12),num=v=>Number(v.str(2)),max=Math.max(1,...data.filter(x=>!x.error).map(x=>num(x.cost)+num(x.div))),n=data.length,W=320,H=130,L2=34,step=W/n,bw=Math.min(22,Math.floor(step*0.6)),fs=9,ct=data.map(x=>x.error?'!':abbr(num(x.cost))),dt=data.map(x=>x.error?'':abbr(num(x.div))),ev=labEvery(ct.concat(dt),step,fs);const bars=data.map((x,i)=>{const cx=Math.round(step*i+step/2),x0=Math.round(cx-bw/2),show=(n-1-i)%ev===0,read=ym(x.month)+(x.partial?' (현재일까지)':'')+(x.error?' · 계산 확인 필요':' · 월말 직접투자 취득원가 '+won(x.cost)+' · 누적 '+BLx()+' 계산상 배당 '+won(x.div));let r='';if(!x.error){const hc=Math.round(num(x.cost)/max*H),hd=Math.round(num(x.div)/max*H);r='<rect class="mu-bar" x="'+x0+'" y="'+(H-hc)+'" width="'+bw+'" height="'+hc+'" fill="#56B9FF"/>'+(hd?'<rect class="mu-bar" x="'+x0+'" y="'+(H-hc-hd)+'" width="'+bw+'" height="'+hd+'" fill="#46E5AC"/>':'')}return '<g class="mu-hit" data-bar="'+i+'" data-read="'+esc(read)+'" tabindex="0" role="button" aria-label="'+esc(read)+'"><rect x="'+Math.round(step*i)+'" y="0" width="'+Math.round(step)+'" height="'+(H+L2)+'" fill="transparent"/>'+r+(show?'<text class="mu-vl mu-vl-cost" x="'+cx+'" y="'+(H+12)+'" text-anchor="middle" font-size="'+fs+'">'+ct[i]+'</text><text class="mu-vl mu-vl-div" x="'+cx+'" y="'+(H+28)+'" text-anchor="middle" font-size="'+fs+'">'+dt[i]+'</text>':'')+'</g>'}).join(''),lastOk=[...data].reverse().find(x=>!x.error),tick=i=>i===0||i===n-1||(n<=6?true:(i%Math.ceil(n/4)===0&&n-1-i>=Math.ceil(n/4)/2+1));return '<div class="mu-legend"><span><i class="mu-sw mu-sw-cost"></i>월말 직접투자 원가</span><span><i class="mu-sw mu-sw-div"></i>누적 계산상 배당('+BLx()+')</span></div><svg class="mu-bars mu-bars-cost" viewBox="0 0 '+W+' '+(H+L2+2)+'" shape-rendering="crispEdges" role="group" aria-label="월별 직접투자 원가와 누적 계산상 배당 비교 막대, 막대를 누르면 정확한 금액">'+'<path d="M0 '+H+'H'+W+'" stroke="#193448"/>'+bars+'</svg><div class="mu-bar-x">'+data.map((x,i)=>'<span>'+(tick(i)?x.month.slice(2).replace('-','.'):'')+'</span>').join('')+'</div><p class="mu-bar-read" aria-live="polite">막대를 누르면 두 금액을 원 단위로 보여 줘요. 막대 아래 숫자: 위 원가 · 아래 누적 배당</p>'+(lastOk?'<dl class="mu-bar-sum"><div><dt>월말 직접투자 원가</dt><dd>'+won(lastOk.cost)+'</dd></div><div><dt>누적 계산상 배당('+BLx()+')</dt><dd class="green">'+won(lastOk.div)+'</dd></div></dl><p class="record-note mu-bar-asof">'+lastOk.month+(lastOk.partial?' 현재일까지':'')+' 기준</p>':'')+'<details class="month-table"><summary>월별 수치 보기</summary><table><thead><tr><th>월</th><th>직접투자 원가</th><th>누적 계산상 배당('+BLx()+')</th></tr></thead><tbody>'+all.map(x=>'<tr><td>'+x.month+(x.partial?'*':'')+'</td>'+(x.error?'<td colspan="2">계산 확인 필요</td>':'<td>'+won(x.cost)+'</td><td>'+won(x.div)+'</td>')+'</tr>').join('')+'</tbody></table></details><p class="record-note mu-chart-note">두 값의 합은 총자산·평가액이 아닙니다.<br>누적 배당은 사용·재투자분 포함 · 시장가 아님</p>'}
function list(p){if(scope.kind==='all'){return '<div class="mu-card-head"><span>'+ic('doc')+'<h2>내 계좌 현황</h2></span><button class="mu-sub-link" data-scope="account">계좌별 보기 →</button></div>'+typeNotice()+'<div class="mu-rows">'+state.accounts.map((a,i)=>{const v=L.project(model,prices,{kind:'account',id:a.account_id});return '<button class="mu-row" data-account="'+esc(a.account_id)+'">'+ic(i%2?'bank':'piggy','account-icon')+'<span class="account-name"><b>'+lblH(a)+'</b><small>'+'배당이 만든 수량 '+ju(v.reinvest_quantity)+'</small></span><span class="mc-acc-val">'+(v.complete?won(v.direct.add(v.reinvest)):'평가 미확인')+'</span><i class="mu-chev" aria-hidden="true"></i></button>'}).join('')+'</div>'+(state.accounts.length?'':'<div class="empty-records">거래를 등록하며 첫 계좌를 만들어 주세요.</div>')}
 if(scope.kind==='account'){return '<div class="mu-card-head"><span>'+ic('stack')+'<h2>계좌 안의 종목</h2></span></div><div class="mu-rows">'+p.holdings.map(h=>{const v=L.project(model,prices,{kind:'instrument',id:h.code,account:h.account_id}),received=recvOf(model,e=>e.account_id===h.account_id&&e.code===h.code);return '<button class="mu-row" data-instrument="'+h.code+'" data-instrument-account="'+esc(h.account_id)+'">'+ic('coin-small','account-icon')+'<span class="account-name"><b>'+esc(name(h.code))+'</b><small>현재 '+ju(h.direct.add(h.reinvest))+' · 배당 '+ju(h.reinvest)+' · 누적 '+BLx()+'배당 '+won(received)+'</small></span><span class="mc-acc-val">'+(v.complete?won(v.total):'시세 미제공')+'<small class="sr-only">종목 상세</small></span><i class="mu-chev" aria-hidden="true"></i></button>'}).join('')+'</div>'+(p.holdings.length?'':'<div class="empty-records">현재 관리 중인 종목이 없습니다. 전량 매도한 원장은 최근 기록과 백업에 보존됩니다.</div>')}
 const nt=notices(p),tile=(i,l,v,c)=>'<div class="mu-tile'+(c?' '+c:'')+'">'+ic(i)+'<span><small>'+l+'</small><b>'+v+'</b></span></div>';return '<div class="mu-stock-head"><h2>'+esc(name(scope.id))+'</h2><div class="mu-hero-meta"><span class="basis">시장가격: '+esc(priceBasis)+'</span>'+(nt?'<a class="mu-pill" href="#mc-notices">종목 알림</a>':'')+'</div><img class="mu-stock-art" src="'+A+'home_medium_sapling.webp" alt="" aria-hidden="true"></div><div class="mu-tiles">'+tile('badge','직접 보유 수량',ju(p.direct_quantity))+tile('recycle','재투자 수량',ju(p.reinvest_quantity))+tile('coin-stack','직접투자 취득원가',won(p.direct_cost))+tile('bars','현재 종목가치',amount(p,p.total))+'</div>'+sharedCash()+'<p class="mc-detail-link"><a class="green" href="detail.html?code='+esc(scope.id)+'">분석 보기 →</a></p>'}
function records(){const ev=model.events.filter(eventScope),acc=e=>lbl(accOf(e.account_id));return '<section class="mu-card mu-rec'+(recEdit?' mc-rec-edit':'')+'"><div class="mu-card-head"><span>'+ic('recdoc')+'<h2>최근 기록</h2></span>'+(ev.length?'<button class="mu-sub-link" data-action="rec-edit" aria-pressed="'+recEdit+'">'+(recEdit?'편집 닫기':'수정·삭제')+'</button>':'')+'</div><div class="mc-rec-list">'+ev.slice(-recordsLimit).reverse().map(e=>{const kind=e.kind==='trade'?e.type:e.kind,desc=e.kind==='dividend'?'<span class="chip">[자동]</span> 배당 +'+won(e.amount):e.kind==='use'?'배당금 사용 −'+won(e.amount):esc(label[e.type])+' '+ju(e.quantity);return '<div class="mu-rec-row record-'+kind+'"><i class="mc-dot" aria-hidden="true"></i><time datetime="'+esc(e.date)+'">'+esc(e.date.slice(2).replace(/-/g,'.'))+'</time><span class="record-description">'+desc+'</span><small class="mc-rec-sub mc-rec-acct">'+lblH(accOf(e.account_id))+'<span class="mc-rec-code"> · '+esc(e.code?name(e.code):'계좌 배당현금')+'</span></small>'+(recEdit?(e.kind==='dividend'?'<span class="auto-readonly">자동 계산 · 수정 불가</span>':'<div class="record-actions"><button class="lab-btn" data-edit="'+esc(e.transaction_id||e.use_id)+'">수정</button><button class="lab-btn" data-delete="'+esc(e.transaction_id||e.use_id)+'">삭제</button></div>'):'')+'</div>'}).join('')+'</div>'+(ev.length?'':'<p class="empty-records">아직 기록이 없습니다.</p>')+(ev.length>recordsLimit?'<button class="mu-more" data-action="more-records">이전 기록 더 보기</button>':'')+'</section>'}
/* v2-stage1 03~05: 계좌·거래 관리 화면(표시 전용). 원장 스키마·계산·저장 변경 없음. 기존 data-action/data-account/data-instrument/data-edit 흐름을 그대로 사용. 구 화면은 ?mode=ledger&legacy=1 */
function lv2Qty(ts){return ts.reduce((v,t)=>t.type==='sell'?v.sub(t.quantity):v.add(t.quantity),L.D.of('0'))}
function lv2Av(txt,i){const c=['#1f6fd1','#1f8a6a','#6a4fb8','#c27a2c','#7a6296','#2f8fb3'][i%6];return '<span class="lv2-av" style="background:'+c+'" aria-hidden="true">'+esc(String(txt||'?').trim().charAt(0).toUpperCase())+'</span>'}
const LV2T={initial_buy:'매수',add_buy:'추가매수',reinvest:'배당재투자',sell:'매도',opening_balance:'기존 보유분'};
function lv2Head(back,title,sub,note){return '<header class="lv2-head">'+back+'<div><h1>'+title+'</h1><p>'+sub+'</p>'+(note?'<small>'+note+'</small>':'')+'</div></header>'}
function ledgerV2(p,nt){let h='';const tx=state.transactions;
if(scope.kind==='instrument'&&scope.account){const a=accOf(scope.account),ts=tx.filter(t=>t.account_id===scope.account&&t.code===scope.id).sort((x,y)=>x.trade_date<y.trade_date?-1:x.trade_date>y.trade_date?1:x.order_key-y.order_key);
h=lv2Head('<button class="lv2-back" data-account="'+esc(scope.account)+'" aria-label="계좌 종목 목록으로">‹</button>',esc(name(scope.id))+' · '+esc(scope.id),esc(a?a.name+(a.type?' · '+a.type:''):'')+' / 거래기록')
+'<section class="lv2-sum"><div><small>보유 수량</small><b>'+ju(lv2Qty(ts))+'</b></div><div><small>거래기록</small><b>'+ts.length+'건</b></div></section>'
+'<div class="lv2-sec"><h2>거래내역</h2><small>각 기록에서 수정</small></div>'
+(ts.length?ts.map(t=>{const amt=L.D.of(t.quantity).mul(t.trade_price);return '<article class="lv2-tx lv2-t-'+esc(t.type)+'"><div class="lv2-tx-top"><time datetime="'+esc(t.trade_date)+'">'+esc(t.trade_date.replace(/-/g,'. '))+'.</time><span class="lv2-chip">'+esc(LV2T[t.type]||t.type)+'</span></div><div class="lv2-tx-body"><span>수량 <b>'+ju(L.D.of(t.quantity))+'</b></span><span>1주당 <b>'+won(L.D.of(t.trade_price))+'</b></span><span class="lv2-amt">거래금액 '+won(amt)+'</span><button class="lv2-edit" data-edit="'+esc(t.transaction_id)+'">수정</button></div></article>'}).join(''):'<p class="lv2-empty">이 종목의 거래기록이 없어요.</p>')
+''}
else if(scope.kind==='account'&&scope.id&&accOf(scope.id)){const a=accOf(scope.id),ts=tx.filter(t=>t.account_id===a.account_id),codes=[...new Set(ts.map(t=>t.code))],nrec=ts.length+state.dividend_uses.filter(u=>u.account_id===a.account_id).length,held=codes.filter(c=>lv2Qty(ts.filter(t=>t.code===c)).cmp('0')>0);
h=lv2Head('<button class="lv2-back" data-scope="all" aria-label="계좌 목록으로">‹</button>',esc(a.name)+(a.type?' · '+esc(a.type):''),'계좌에 등록된 종목을 선택하세요.')
+'<section class="lv2-sum lv2-sum-acc"><h3>이 계좌의 기록</h3><div><span>보유 종목 <b>'+held.length+'개</b></span><span>거래기록 <b>'+nrec+'건</b></span></div></section>'
+'<div class="lv2-sec"><h2>보유 종목 목록</h2><small>종목 선택 ›</small></div><div class="lv2-list">'
+(held.length?held.map((c,i)=>{const q=lv2Qty(ts.filter(t=>t.code===c)),n=ts.filter(t=>t.code===c).length;return '<button class="lv2-row" data-instrument="'+esc(c)+'" data-instrument-account="'+esc(a.account_id)+'">'+lv2Av(name(c),i)+'<span class="lv2-txt"><b>'+esc(name(c))+'</b><small>'+esc(c)+' · '+(q.cmp('0')>0?'보유 '+ju(q):'매도 완료 · 거래 '+n+'건')+'</small><em>거래내역 보기</em></span><i class="lv2-chev" aria-hidden="true">›</i></button>'}).join(''):'<p class="lv2-empty">'+(codes.length?'현재 보유 중인 종목이 없어요.':'아직 이 계좌에 거래기록이 없어요.')+'</p>')
+'</div>'+(()=>{const sold=codes.filter(c=>!held.includes(c));return sold.length?'<details class="lv2-sold"><summary>매도 완료 종목 이력 <b>'+sold.length+'</b><small>0주 종목 · 거래기록 보존</small></summary><div class="lv2-list">'+sold.map((c,i)=>((c,i)=>{const q=lv2Qty(ts.filter(t=>t.code===c)),n=ts.filter(t=>t.code===c).length;return '<button class="lv2-row" data-instrument="'+esc(c)+'" data-instrument-account="'+esc(a.account_id)+'">'+lv2Av(name(c),i)+'<span class="lv2-txt"><b>'+esc(name(c))+'</b><small>'+esc(c)+' · '+(q.cmp('0')>0?'보유 '+ju(q):'매도 완료 · 거래 '+n+'건')+'</small><em>거래내역 보기</em></span><i class="lv2-chev" aria-hidden="true">›</i></button>'})(c,i+held.length)).join('')+'</div></details>':''})()}
else{h=lv2Head('<a class="lv2-back" href="asset-hub.html" aria-label="자산관리 선택으로">‹</a>','계좌 · 거래 관리','내 계좌와 거래기록을 관리합니다.')
+'<button class="lv2-cta" data-action="trade"><span aria-hidden="true">+</span> 거래 등록</button>'
+'<div class="lv2-sec"><h2>내 계좌 목록</h2><small>'+state.accounts.length+'개 계좌</small></div><div class="lv2-list">'
+(state.accounts.length?state.accounts.map((a,i)=>{const ts=tx.filter(t=>t.account_id===a.account_id),held=[...new Set(ts.map(t=>t.code))].filter(c=>lv2Qty(ts.filter(t=>t.code===c)).cmp('0')>0).length,n=ts.length+state.dividend_uses.filter(u=>u.account_id===a.account_id).length;return '<button class="lv2-row" data-account="'+esc(a.account_id)+'">'+lv2Av(a.name,i)+'<span class="lv2-txt"><b>'+esc(a.name)+'</b><small>'+esc(a.type||'종류 미확인')+'</small><em>보유 종목 '+held+'개 · 거래기록 '+n+'건</em></span><i class="lv2-chev" aria-hidden="true">›</i></button>'}).join(''):'<p class="lv2-empty">거래를 등록하면 첫 계좌가 만들어져요.</p>')
+'</div><hr class="lv2-hr"><div class="lv2-sec lv2-sec-col"><h2>데이터 보관</h2><small>현재 거래기록을 보관하거나 복원합니다.</small></div><div class="lv2-br"><button class="lv2-bk" data-action="backup">↓ 백업</button><button class="lv2-rs" data-action="restore">↑ 복원</button></div><p class="lv2-foot">복원 시 기존 데이터 변경 여부를 먼저 확인합니다.</p>'
+'<details class="lv2-more"><summary>기타 관리 도구</summary>'+tools()+'</details>'}
return '<div class="lv2"><a class="lv2-logo" href="index.html">돈냄새연구소</a>'+h+'</div>'+(nt?'<div id="mc-notices" class="mu-notices">'+nt+'</div>':'')}
/* UI routing only: derive mode from URL; never write ledger storage. */
const MODES={performance:['배당이 키운 자산','배당이 키운 자산과 수량, 배당 흐름을 살펴봐요.'],ledger:['계좌·거래 관리','계좌와 거래 기록을 관리하고 백업해요.'],composition:['내 투자금','현재 보유 직접투자 취득원가의 구성이에요.'],dividends:['배당 성과 분석','받은 배당의 시간 흐름을 원장 기록으로 봐요.'],tr:['배당주 투자성과','가격 변화와 실제 받은 배당'],weather:['미래 날씨','보유 배당주 기준 세 가지 가상 시나리오']};
function assetMode(){const q=new URLSearchParams(location.search),m=q.get('mode');if(m==='performance'&&!q.has('legacy'))return 'tr';return MODES[m]?m:'ledger'}
function assetModeUrl(mode){const u=new URL(location.href);u.searchParams.set('mode',mode);return u.pathname+u.search+u.hash}
function assetBreadcrumb(){return '<a class="asset-breadcrumb" href="asset-hub.html">← 자산관리 선택으로</a>'}
function assetModeHeader(mode){const [t,sub]=MODES[mode];return '<section class="mu-banner"><div><h1>'+t+'</h1><p>'+sub+'</p>'+(mode==='ledger'?'<a class="mu-sub-link" href="'+esc(assetModeUrl('dividends'))+'">배당 성과 분석으로 →</a>':'<a class="mu-sub-link" href="asset-hub.html">← 홈으로</a>')+'</div><img src="'+A+'management_glowing_tree.webp" alt="" aria-hidden="true"></section>'}
function recentCount(){const d=new Date(L.today()+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-30);const cut=d.toISOString().slice(0,10);return state.transactions.filter(t=>t.trade_date>=cut).length+state.dividend_uses.filter(u=>u.use_date>=cut).length}
function tools(){const t=(a,i,h,s)=>'<button class="mu-tool" data-action="'+a+'">'+ic(i)+'<span><b>'+h+'</b><small>'+s+'</small></span><i class="mu-chev" aria-hidden="true"></i></button>';return '<div class="mu-tools">'+t('receipt','coin-small','실입금 확인','증권사 월 입금 입력')+t('opening','stack','기존 보유분 등록','수량·평균단가 입력')+t('acctype','bank','계좌 종류','확인·수정')+t('use','wallet','배당금 사용','사용 처리')+t('backup','doc','백업 저장','파일로 저장')+t('restore','cloud','백업 복원','파일 불러오기')+t('rollback','clock','되돌리기','직전 수정·삭제')+'</div><details class="asset-protected mu-danger"><summary><b>기록초기화(위험)</b><small>모든 거래 기록을 삭제합니다. 먼저 백업하세요.</small></summary><p class="record-note">기록 초기화는 계좌와 거래 기록을 지웁니다. 기존 확인 절차를 거쳐 진행합니다.</p><button class="lab-btn" data-action="reset">기록 초기화</button></details>'}
