const PAL=['#FFC83D','#56B9FF','#46E5AC','#FF83AC','#B59AFF','#FFAA66','#45DCE5','#83A5FF'],PAL_ETC='#6B7280',PAL_ZERO='#213B4B';
function palHash(k){let h=2166136261;for(const c of String(k)){h^=c.codePointAt(0);h=Math.imul(h,16777619)>>>0}return h%PAL.length}
function palMap(keys){const m=new Map();keys.forEach((k,i)=>m.set(k,i<PAL.length?PAL[i]:PAL_ETC));return m}
function abbr(v){const a=Math.abs(v);if(a===0)return '0';if(a<1e4)return Math.round(v).toLocaleString('ko-KR');if(a<1e6)return (v/1e4).toFixed(1).replace(/\.0$/,'')+'만';if(a<1e8)return Math.round(v/1e4).toLocaleString('ko-KR')+'만';if(a<1e10)return (v/1e8).toFixed(1).replace(/\.0$/,'')+'억';return Math.round(v/1e8).toLocaleString('ko-KR')+'억'}
function labW(t,fs){return [...t].reduce((w,c)=>w+(/[만억]/.test(c)?fs:fs*0.6),0)}
function labEvery(texts,step,fs){const m=Math.max(0,...texts.map(t=>labW(t,fs)));return m<=step-2?1:m<=2*step-2?2:3}
function ym(m){return m.replace('-','.')}
function donut(rows,total,aria){if(total.cmp('0')<=0)return '';const pos=rows.filter(r=>r.amt&&r.amt.cmp('0')>0),top=pos.slice(0,5),rest=pos.slice(5);const cm=palMap(top.map(r=>r.key));const segs=top.map(r=>({v:Number(r.amt.str(8)),c:cm.get(r.key),n:r.name,k:r.key}));if(rest.length)segs.push({v:rest.reduce((v,r)=>v+Number(r.amt.str(8)),0),c:PAL_ETC,n:'기타 '+rest.length+'개',k:'__etc'});const T=segs.reduce((v,x)=>v+x.v,0),C=2*Math.PI*42;let off=0;const arcs=segs.map(x=>{const len=x.v/T*C,el='<circle cx="60" cy="60" r="42" fill="none" stroke="'+x.c+'" stroke-width="16" data-seg="'+esc(x.k)+'" data-color="'+x.c+'" stroke-dasharray="'+len.toFixed(3)+' '+(C-len).toFixed(3)+'" stroke-dashoffset="'+(-off).toFixed(3)+'" transform="rotate(-90 60 60)"><title>'+esc(x.n)+'</title></circle>';off+=len;return el}).join('');const tw=won(total);return '<div class="mu-donut-wrap"><svg class="mu-donut" viewBox="0 0 120 120" role="img" aria-label="'+esc(aria||'현재 보유 직접투자 취득원가 구성 도넛')+'"><circle cx="60" cy="60" r="42" fill="none" stroke="#213B4B" stroke-width="16"/>'+arcs+'</svg><div class="mu-donut-c"><small>'+(aria&&aria.includes('확인 가능')?'확인분 합계':'합계')+'</small><b class="'+(tw.length>12?'mu-long':'')+'">'+tw+'</b></div></div>'}
