function bpAccMix(a){const Z=L.D.of('0');let d=Z,gv=Z,gc=Z;for(const h of model.holdings){if(h.account_id!==a||h.direct.add(h.reinvest).cmp('0')<=0)continue;let x=null;try{x=holdVal(h)}catch(_){}if(x===null)continue;if(tv2KindOf(h.code).endsWith('div'))d=d.add(x);else{gv=gv.add(x);gc=gc.add(h.direct_cost).add(h.reinvest_cost)}}return '<section class="pv-card bp-mix" data-div="'+d.str(0)+'" data-gen="'+gv.str(0)+'" data-gpnl="'+gv.sub(gc).str(0)+'"><h3>이 계좌 자산</h3><div class="bp-kv"><span><em>배당주 평가액</em><b>'+won(d)+'</b></span><span><em>일반주식 평가액</em><b>'+won(gv)+'</b></span><span><em>일반주식 손익</em><b class="'+(gv.sub(gc).cmp('0')<0?'neg':'pos')+'">'+bpS(gv.sub(gc))+'</b></span><span><em>계좌 합계</em><b>'+won(d.add(gv))+'</b></span></div><a class="bp-core" href="management.html?mode=ledger">일반주식 관리 ›</a></section>'}
