/* t281ua1 B·C·D 비교 그래프. 비교선=기존 comparison-worker(CORE TR 지수, 기존 계산식). 내 선=기존 원장 재생(RP) 보유수량×CORE 종가(clsp) + 확인된 실수령.
   기준 통일: 선택 기간 첫 공통 관측일 s를 0%로. 내 선(t) = [P(t) − P(s)] ÷ 투자기준금액(t), P = 평가액 − 투자기준금액 + 누적 실수령(기존 누적성과 정의 그대로). 기간 시작 전 미보유면 P(s)=0. */
let bpPer='1년',bpWk=null,bpSeq=0;const bpNav={},BPREF=[['069500','KODEX 200','#56B9FF','reference'],['379800','KODEX 미국S&P500','#FF83AC','reference'],['229200','KODEX 코스닥150','#B59AFF','reference'],['458730','TIGER 미국배당다우존스','#46E5AC','etf']];
