  const S=res.series.filter((r,i,a)=>!(i>0&&a[i-1].date===r.date)),dates=S.map(r=>r.date),s0=dates[0];
  const codes=[...new Set((state.transactions||[]).filter(x=>fh({code:x.code,account_id:x.account_id})&&isDiv(x)).map(x=>x.code))];for(const c of codes){try{await bpNavOf(c,'etf')}catch(_){}}
  const first=bpFirst(h=>fh(h)&&isDiv(h));
  const rc=rcCore(),ev=[];for(const e of model.events){if(e.kind!=='dividend'||!fh(e))continue;const x=rc.st.get(e);if(!x||x.s==='hold')continue;if(t==='code'&&x.s==='month')continue;ev.push([e.date,Number(x.amt.str(0))])}
  if(t!=='code')for(const o of rc.off)if(t!=='acc'||o.account_id===acc)ev.push([(o.month||'')+'-28',Number(o.amt.str(0))]);
