  const cand=dates.filter(d=>first&&d>=first),step=Math.max(1,Math.ceil(cand.length/40)),sd=new Set(cand.filter((d,i)=>i%step===0||i===cand.length-1));
  const P0=first&&first<=s0?P(s0):{pl:0,c:0};const mine=new Map();for(const d of dates){if(!first||d<first){mine.set(d,0);continue}if(!sd.has(d))continue;const x=P(d);if(x.c>0)mine.set(d,(x.pl-P0.pl)/x.c*100)}
  const nm=it.map(x=>x.code),lines=[];
  BPREF.forEach(r=>{const ix=nm.indexOf(r[0]);if(ix<0||!bpOn.has(r[0]))return;lines.push({k:r[0],lab:esc(r[1])+' TR',col:r[2],w:1.4,ys:S.map(x=>Number(x.tr[ix])-100)})});
