  lines.push({k:'me',lab:'내 배당주 성과',col:BPME,w:3.4,ys:dates.map(d=>mine.has(d)?mine.get(d):null)});
  const W=320,Hh=170,PR=52,all=lines.flatMap(l=>l.ys).filter(y=>y!=null&&isFinite(y)),mn=Math.min(0,...all),mx=Math.max(0,...all),sp=(mx-mn)||1,X=i=>6+i/(Math.max(1,dates.length-1))*(W-PR-6),Y=y=>10+(mx-y)/sp*(Hh-20);
  const path=ys=>{let s='',pen=false;ys.forEach((y,i)=>{if(y==null||!isFinite(y))return;s+=(pen?'L':'M')+X(i).toFixed(1)+' '+Y(y).toFixed(1);pen=true});return s};
  const fmt1=y=>y==null?'—':(y>0?'+':'')+y.toFixed(1)+'%';const lastOf=ys=>{for(let i=ys.length-1;i>=0;i--)if(ys[i]!=null&&isFinite(ys[i]))return ys[i];return null};
  const lab=lines.map(l=>({l,v:lastOf(l.ys)})).filter(x=>x.v!=null).map(x=>Object.assign(x,{y:Y(x.v)})).sort((a,b)=>a.y-b.y);for(let i=1;i<lab.length;i++)if(lab[i].y-lab[i-1].y<11)lab[i].y=lab[i-1].y+11;const ov=lab.length?lab[lab.length-1].y-(Hh-4):0;if(ov>0)lab.forEach(x=>x.y-=ov);
