  const H=bpHold(fh),R=bpRecv(t==='code'?(e=>e.code===code):t==='acc'?(e=>e.account_id===acc):()=>true,t==='code'?undefined:t==='acc'?acc:null),rt=res.returns||[],rtOf=c=>{const r=rt.find(x=>x.ticker===c);return r?Number(r.tr_return):null};
